# -*- coding: utf-8 -*-
"""Épreuves APC du collège : structure commune. 18 points pour les consignes + 2 points de perfectionnement (maîtrise de la langue, soin)."""
GRILLE = [("CM1", "Interprétation correcte de la situation (compréhension de la tâche et des consignes)"),
          ("CM2", "Utilisation correcte des outils de la discipline (savoirs, techniques, vocabulaire)"),
          ("CM3", "Cohérence interne de la production (logique, enchaînement, justesse des résultats)"),
          ("CP", "Perfectionnement : maîtrise de la langue, soin et présentation (2 points)")]


def E(matiere, niveau, duree, competence, situation, support, tache, items):
    return dict(matiere=matiere, niveau=niveau, duree=duree, competence=competence, situation=situation, support=support, tache=tache,
                items=[dict(consigne=c, points=p, correction=r) for c, p, r in items], perfectionnement=2, total=sum(p for _c, p, _r in items) + 2)


